//! Idempotency keys. `command_id` is generated by the client; a retried
//! command returns the originally stored response instead of re-executing.
//!
//! The key row is written in the same transaction as the state change, so
//! "processed" and "recorded" are atomic.

use sqlx::PgConnection;
use uuid::Uuid;

pub async fn find(
    conn: &mut PgConnection,
    command_id: Uuid,
) -> Result<Option<serde_json::Value>, sqlx::Error> {
    sqlx::query_as::<_, (serde_json::Value,)>(
        "SELECT response FROM idempotency_keys WHERE command_id = $1",
    )
    .bind(command_id)
    .fetch_optional(conn)
    .await
    .map(|row| row.map(|(value,)| value))
}

/// Insert the stored response unless the key already exists.
/// Returns `true` when this call claimed the command.
pub async fn insert_if_absent(
    conn: &mut PgConnection,
    command_id: Uuid,
    user_id: Uuid,
    kind: &str,
    response: &serde_json::Value,
) -> Result<bool, sqlx::Error> {
    let affected = sqlx::query(
        "INSERT INTO idempotency_keys (command_id, user_id, kind, response) \
         VALUES ($1, $2, $3, $4) ON CONFLICT (command_id) DO NOTHING",
    )
    .bind(command_id)
    .bind(user_id)
    .bind(kind)
    .bind(response)
    .execute(conn)
    .await?
    .rows_affected();
    Ok(affected == 1)
}
